            if (windows.count > 0) window = windows[0];
        }
        if (!window) { fprintf(stderr, "PHAROS_INPUT_STATE no_window\n"); return; }
        id client = window.firstResponder;
        if (![client respondsToSelector:@selector(setMarkedText:selectedRange:replacementRange:)]) {
            client = nil;
            NSMutableArray *stack = [NSMutableArray arrayWithObject:window.contentView];
            while (stack.count > 0 && client == nil) {
                NSView *view = stack.lastObject;
                [stack removeLastObject];
                if ([view respondsToSelector:@selector(setMarkedText:selectedRange:replacementRange:)]) {
                    client = view;
